#!/usr/bin/env bash
# Every function's description and grants, in one place. Regenerates
# functions/<name>/<name>.json; never edit those by hand.
#   table        read          table:rw   + write rows       table:rwd  + delete rows
#   /folder:verbs              connector:<id>
set -euo pipefail
cd "$(dirname "$0")/.."
f() { uv run --no-project python bin/fnjson.py "$@"; }
f mail_settings_ensure "Make sure the caller has Mail settings and the five starting categories. Safe on every visit." mail_settings:rw mail_category:rw
f mail_connect "Set-up: hold the mail_mailbox the person connected (or the sample), with their settings and starting categories." mail_mailbox:rw mail_settings:rw mail_category:rw mail_activity:rw
f mail_sync "Read Gmail, Outlook or the sample mail_mailbox into conversations, messages and one document per conversation. Resumable and idempotent: the first read, push and the catch-up all call this." mail_mailbox:rw conversation:rw mail_thread:rw message:rw mail_sync_state:rw draft:rw mail_settings mail_activity:rw /mail-sample:read,write connector:gmail connector:outlook
f mail_sort "Sort what is waiting with one Decisions call per conversation: category, what it needs, priority, and promises either way. Starts drafts and promise notes where text is needed." conversation:rw mail_thread:rw mail_category mail_rule mail_correction mail_settings mail_mailbox person person_handle promise mail_activity:rw /mail-sample:read
f mail_people "Recompute who the owner deals with from their mail: counts, reciprocity, cadence and weight per person." message conversation mail_mailbox person:rw person_handle:rw
f mail_setup_report "Set-up: what the first read found, for the set-up agent: the owner's own writing, people, domains, bulk senders and totals." mail_settings mail_mailbox conversation mail_thread person person_handle mail_category /mail-sample:read
f mail_setup_proposals "Set-up: shape the set-up agent's proposals (categories, voice, rules, VIPs) into the form the person edits." mail_settings:rw mail_category person person_handle
f mail_setup_apply "Set-up: apply the categories form: what the person kept, renamed, dropped or added, their voice, rules and VIPs." mail_category:rw mail_rule:rw person:rw person_handle mail_settings:rw mail_activity:rw brand
f mail_setup_drafts "Set-up: apply which categories get replies drafted, and plan the first sort." mail_category:rw mail_settings:rw conversation mail_thread
f mail_setup_done "Set-up: count what the first sort found and open the inbox on it." conversation mail_thread mail_settings:rw mail_activity:rw
f mail_thread_action "Do one thing to conversations (done, restore, read, unread, snooze, unsnooze, mute, move, state, draft) here and in Gmail or Outlook. A move is kept as a correction the sort learns from." conversation:rw mail_thread:rw mail_mailbox mail_category mail_correction:rw mail_settings person person_handle mail_activity:rw /mail-sample:read connector:gmail connector:outlook
f mail_promise_context "Gather one conversation for the promise reader: the newest messages, which way the promise went, and promises already open." conversation mail_thread:rw promise mail_settings mail_mailbox /mail-sample:read
f mail_save_promises "Store the promises the reader found, with their sentence and date, and close the ones a newer message kept." promise:rw conversation mail_thread:rw mail_activity:rw
f mail_writing_context "Gather everything the writer needs for one draft: voice, rules, the conversation, who to reply to, what is known about the other side, past lines to them, open promises." conversation mail_thread:rw mail_mailbox mail_settings mail_rule person person_handle promise message /mail-sample:read mail_category brand /brand:read
f mail_save_draft "Store the writer's draft (or its reason for not writing one), note what the other side wants, and mark the draft ready." conversation:rw mail_thread:rw draft:rw mail_activity:rw
f mail_send_draft "Deliver one approved draft from its conversation's mailbox, in that conversation. Refuses anything not approved, never sends twice, holds a future send time, refuses the sample mailbox." draft:rw conversation:rw mail_thread:rw mail_mailbox mail_settings mail_activity:rw connector:gmail connector:outlook
f mail_sweep "The hourly pass: bring snoozed conversations back, turn due follow-ups into ready nudges, list approved drafts whose send time came." conversation:rw mail_thread:rw draft mail_mailbox mail_activity:rw
f mail_resort "Send recent open conversations back to be sorted after categories change." conversation:rw mail_thread:rw mail_activity:rw
f mail_sample_data "Load or clear the made-up sample mailbox (36 conversations at .example addresses), so Mail can be seen working and tested without anyone's mail. Clear removes every row and file it made, and a person it made only when nothing else in the Lemma (a meeting, or another source's promise, conversation, message or draft) knows them." mail_mailbox:rwd conversation:rwd mail_thread:rwd message:rwd draft:rwd promise:rwd person:rwd person_handle:rwd mail_sync_state:rwd mail_correction:rwd mail_nudge:rwd mail_activity:rwd mail_category:rwd mail_rule:rwd mail_settings:rwd mail_sample_row:rwd needs_you:rw meeting /mail-sample:read,write,delete
f mail_needs_you "Mail's part of the person's day on the shared needs_you list: replies owed (answer), promises they made (do) and promises owed to them (waiting), with Mail's drafts; resolves what no longer needs them. settle_item_id: a promise item the person marked done elsewhere closes the promise." conversation mail_thread message promise:rw draft person person_handle mail_nudge needs_you:rw
f mail_nudge_check "Worth a nudge yet? One Decisions call per mail conversation where a promise owed to the person is late (with their meetings with that person as evidence); a yes asks the writer for the follow-up in their voice." conversation mail_thread:rw promise message draft meeting person person_handle mail_settings mail_nudge:rw
f mail_promise_kept "Was this promise kept? One Decisions call per mail conversation that got a new message, one question per open promise (yes closes it; not sure asks the person as a decide item on needs_you)." promise:rw conversation message mail_settings needs_you:rw
f mail_search "Find mail for the person: what Mail has read, and through Gmail's or Outlook's own search, mail older than or outside the first read (about 30 days). Plain words, optionally from_handle and after/before (YYYY-MM-DD). Each hit says where it was found, whether Mail holds the conversation (conversation_id) and a link to open it in Gmail or Outlook. Reads only." conversation mail_mailbox /mail-sample:read connector:gmail connector:outlook
f mail_memory "Tells this Lemma's agents that Mail is installed: Mail's own block in /memory/AGENTS.md and its guide at /memory/plugins/mail.md and, run as the person, their own block in /me/AGENTS.md pointing at their voice, leaving the team's notes alone. Set-up runs it; safe to run again. remove takes them out." /memory:read,write
